frappe.ui.form.on("Job Offer", {
    job_applicant: function(frm) {
        if (!frm.doc.job_applicant) {
            console.warn("job_applicant is empty, skipping fetch.");
            return;
        }

        frappe.db.get_value("Job Applicant", frm.doc.job_applicant, 
            ["custom_expected_ctc", "custom_current_ctc", "custom_current_employer", 
             "custom_current_designation", "custom_notice_period", 
             "custom_current_location", "custom_preferred_location"],
            function(data) {
                if (!data) return;

                console.log("Fetched data:", data);

                // ✅ FIX: custom_expected_ctc is stored as "1cr", "10L" etc.
                // Show the raw value directly — don't force parseFloat
                if (data.custom_expected_ctc !== null && 
                    data.custom_expected_ctc !== undefined &&
                    data.custom_expected_ctc !== "") {

                    // Since custom_proposed_ctc is Currency type,
                    // we need a clean number — strip all non-numeric chars
                    let raw = String(data.custom_expected_ctc).trim();
                    let numeric = parseFloat(raw.replace(/[^0-9.]/g, ""));

                    if (!isNaN(numeric)) {
                        frm.set_value("custom_proposed_ctc", numeric);
                        frm.refresh_field("custom_proposed_ctc");
                        console.log("Set proposed CTC to:", numeric);
                    } else {
                        // Value like "1cr" can't be auto-converted — show warning
                        frappe.show_alert({
                            message: `Expected CTC is "${raw}" — please enter manually`,
                            indicator: "orange"
                        }, 5);
                        console.warn("Cannot auto-convert CTC value:", raw);
                    }
                }
            }
        );
    }
});

frappe.ui.form.on('Job Offer', {

    // ── When Job Requisition changes → fetch CTC & Designation ──
    custom_job_requisition(frm) {
        if (!frm.doc.custom_job_requisition) {
            frm.set_value('custom_proposed_ctc', '');
            return;
        }
        frappe.db.get_value(
            'Job Requisition',
            frm.doc.custom_job_requisition,
            ['custom_proposed_salarybudget', 'designation']
        ).then(r => {
            if (!r.message) return;
            let data = r.message;

            if (data.custom_proposed_salarybudget) {
                let raw = String(data.custom_proposed_salarybudget).trim();
                let numericMatch = raw.match(/[\d,]+(\.\d+)?/);
                if (numericMatch) {
                    let numeric = parseFloat(numericMatch[0].replace(/,/g, ""));
                    if (!isNaN(numeric)) {
                        frm.set_value('custom_proposed_ctc', numeric);
                        frappe.show_alert({
                            message: __('Proposed CTC fetched from Job Requisition'),
                            indicator: 'green'
                        });
                    }
                }
            }

            if (data.designation && !frm.doc.designation) {
                frm.set_value('designation', data.designation);
            }
        });
    }
});

frappe.ui.form.on('Attendance Request', {
    refresh(frm) {
        frm.set_df_property('to_date', 'read_only', 1);
    },
    reason(frm) {
        validate_date_not_future(frm, 'from_date');
        validate_date_not_future(frm, 'to_date');
        if (frm.doc.from_date) {
            frm.set_value('to_date', frm.doc.from_date);
        }
        fetch_permission_details(frm);
    },
    employee(frm) {
        fetch_permission_details(frm);
    },
    from_date(frm) {
        if (frm.doc.from_date) {
            frm.set_value('to_date', frm.doc.from_date);
        }
        validate_date_not_future(frm, 'from_date');
        fetch_permission_details(frm);
    },
    to_date(frm) {
        validate_date_not_future(frm, 'to_date');
    }
});
function validate_date_not_future(frm, fieldname) {
    if (frm.doc.reason !== 'Regularization' || !frm.doc[fieldname]) {
        return;
    }
    if (frappe.datetime.get_diff(frm.doc[fieldname], frappe.datetime.now_date()) > 0) {
        frappe.show_alert({
            message: __('Regularization requests cannot be created for future dates.'),
            indicator: 'red'
        });
        frm.set_value(fieldname, '');
    }
}
function fetch_permission_details(frm) {
    if (
        !['Late In', 'Early Out'].includes(frm.doc.reason) ||
        !frm.doc.employee ||
        !frm.doc.from_date
    ) {
        return;
    }
    frappe.show_progress('Calculating...', 50, 100, 'Fetching shift and checkin data');
    frappe.call({
        method: 'hrms_custom.overrides.attendance_request.get_permission_details',
        args: {
            employee: frm.doc.employee,
            permission_date: frm.doc.from_date,
            permission_type: frm.doc.reason
        },
        callback(r) {
            frappe.hide_progress();
            if (!r.message) {
                return;
            }
            const d = r.message;
            frm.set_value('custom_permission_from_time', d.permission_from_time);
            frm.set_value('custom_permission_to_time', d.permission_to_time);
            frm.set_value('custom_permission_hours', d.permission_hours);
            if (d.message) {
                frappe.show_alert({
                    message: d.message,
                    indicator: 'orange'
                }, 8);
            } else {
                frappe.show_alert({
                    message: `${frm.doc.reason}: ${d.permission_from_time.substring(11, 16)} to ${d.permission_to_time.substring(11, 16)} (${d.permission_hours} hrs)`,
                    indicator: 'blue'
                }, 6);
            }
        },
        error() {
            frappe.hide_progress();
        }
    });
}

