frappe.ui.form.on('Job Applicant', {
    create_dialog: function (frm) {
        let d = new frappe.ui.Dialog({
            title: __("Enter Interview Type"),
            fields: [
                {
                    label: "Interview Type",
                    fieldname: "interview_type",
                    fieldtype: "Link",
                    options: "Interview Type",
                    reqd: 1,
                    get_query: function () {
                        return {
                            filters: [["designation", "=", frm.doc.designation]],
                        };
                    },
                },
            ],
            primary_action_label: __("Create Interview"),
            primary_action(values) {
                if (!values.interview_type) {
                    frappe.msgprint(__("Please select an Interview Type"));
                    return;
                }
                frm.events.create_interview(frm, values);
                d.hide();
            },
        });
        d.show();
    },
});

frappe.ui.form.on('Interview', {
    setup: function(frm) {
        var _orig_throw = frappe.throw;
        frappe.throw = function(msg) {
            if (typeof msg === 'string' && msg.includes('Select Interview Type First')) {
                return;
            }
            return _orig_throw.apply(this, arguments);
        };
        frm._pending_job_applicant = 
            (frappe.route_options && frappe.route_options.job_applicant) || null;
    },

    onload: function(frm) {
        var job_applicant = frm._pending_job_applicant || frm.doc.job_applicant;

        if (job_applicant) {
            frappe.db.get_list('Interview Type', { limit: 1 }).then(function(data) {
                if (data && data.length > 0) {
                    frm.doc.interview_type = data[0].name;
                    frm.refresh_field('interview_type');

                    if (!frm.doc.job_applicant) {
                        frm.set_value('job_applicant', job_applicant);
                    }
                }
            });
            frm._original_job_applicant = job_applicant;
        }
    },

    interview_type: function(frm) {
        var ja = frm._original_job_applicant || frm._pending_job_applicant;
        if (ja) {
            setTimeout(function() {
                if (!frm.doc.job_applicant) {
                    // Use set_value (not direct assignment) so fetch_from fields also load
                    frm.set_value('job_applicant', ja);
                }
            }, 200);
        }
    }
});

frappe.ui.form.on('Attendance Reason Allocation', {
    refresh(frm) {
        toggle_fields(frm);
    },
    applies_to(frm) {
        frm.set_value('employee', '');
        frm.set_value('employee_name', '');
        frm.set_value('department', '');
        toggle_fields(frm);
    }
});

function toggle_fields(frm) {
    let is_employee   = frm.doc.applies_to === 'Employee';
    let is_department = frm.doc.applies_to === 'Department';

    frm.set_df_property('employee',      'hidden', is_employee   ? 0 : 1);
    frm.set_df_property('employee_name', 'hidden', is_employee   ? 0 : 1);
    frm.set_df_property('department',    'hidden', is_department ? 0 : 1);

    frm.fields_dict['employee']      && frm.fields_dict['employee'].refresh();
    frm.fields_dict['employee_name'] && frm.fields_dict['employee_name'].refresh();
    frm.fields_dict['department']    && frm.fields_dict['department'].refresh();
}

