frappe.ui.form.on('Job Applicant', {
    refresh(frm) {
        // Show Send Pre-Offer Form button
        if (!frm.is_new()) {

            if (frm.doc.custom_preoffer_form_sent) {
                // Already sent — show resend button
                frm.add_custom_button(__('Resend Pre-Offer Form'), function() {
                    send_preoffer_form(frm);
                }, __('Pre-Offer')).addClass('btn-warning');

                // Show sent info
                frm.set_intro(
                    __('Pre-Offer Form sent on {0} by {1}',
                    [
                        frappe.datetime.str_to_user(frm.doc.custom_preoffer_sent_on),
                        frm.doc.custom_preoffer_sent_by
                    ]),
                    'green'
                );
            } else {
                // Not sent yet — show send button
                frm.add_custom_button(__('Send Pre-Offer Form'), function() {
                    send_preoffer_form(frm);
                }, __('Pre-Offer')).addClass('btn-primary');
            }
        }
    }
});

function send_preoffer_form(frm) {
    // Confirm before sending
    frappe.confirm(
        __('Send Pre-Offer Form to <b>{0}</b> ({1})?',
        [frm.doc.applicant_name, frm.doc.email_id]),
        function() {
            frappe.call({
                method: 'hrms_custom.api.send_preoffer_form',
                args: {
                    job_applicant: frm.doc.name
                },
                freeze: true,
                freeze_message: __('Sending Pre-Offer Form...'),
                callback: function(r) {
                    if (!r.exc) {
                        frappe.show_alert({
                            message: __('Pre-Offer Form sent to {0}!',
                                [frm.doc.applicant_name]),
                            indicator: 'green'
                        }, 5);
                        frm.reload_doc();
                    }
                }
            });
        }
    );
}

frappe.ui.form.on('Job Offer', {
    refresh(frm) {
        if (!frm.is_new()) {

            // Show offer response status
            if (frm.doc.custom_offer_response === 'Accepted') {
                frm.set_intro('Candidate has ACCEPTED the offer!', 'green');
            } else if (frm.doc.custom_offer_response === 'Rejected') {
                frm.set_intro('Candidate has DECLINED the offer.', 'red');
            } else if (frm.doc.custom_offer_sent) {
                frm.set_intro('Offer Letter sent. Awaiting candidate response...', 'orange');
            }

            if (frm.doc.custom_offer_sent) {
                // Resend button
                frm.add_custom_button(__('Resend Offer Letter'), function() {
                    send_offer_letter(frm);
                }, __('Offer Letter')).addClass('btn-warning');
            } else {
                // Send button
                frm.add_custom_button(__('Send Offer Letter'), function() {
                    send_offer_letter(frm);
                }, __('Offer Letter')).addClass('btn-success');
            }
        }
    }
});

function send_offer_letter(frm) {
    let candidate = frm.doc.applicant_name || frm.doc.job_applicant;
    frappe.confirm(
        __('Send Offer Letter to <b>{0}</b>?<br><br>Candidate will receive an email with Accept/Reject buttons.', [candidate]),
        function() {
            frappe.call({
                method: 'hrms_custom.api.send_offer_letter',
                args: { job_offer: frm.doc.name },
                freeze: true,
                freeze_message: __('Sending Offer Letter...'),
                callback: function(r) {
                    if (!r.exc && r.message && r.message.success) {
                        frappe.show_alert({
                            message: r.message.message,
                            indicator: 'green'
                        }, 7);
                        frm.reload_doc();
                    }
                }
            });
        }
    );
}

frappe.ui.form.on('Employee Onboarding', {

    // ── On refresh: handle pre-filled fields ──
    refresh(frm) {
        if (frm.is_new()) {
            if (frm.doc.job_applicant && !frm.doc.job_offer) {
                frm.trigger('job_applicant');
            } else if (frm.doc.job_offer && !frm.doc.employee_name) {
                frm.trigger('job_offer');
            }
        }
    },

    // ── When Job Applicant is set → auto-find Job Offer + fetch candidate details ──
    job_applicant(frm) {
        if (!frm.doc.job_applicant) {
            frm.set_value('custom_blood_group_', '');
            frm.set_value('custom_emergency_phone_number', '');
            return;
        }

        // Step 1: Auto-find & set Job Offer from Job Applicant
        if (!frm.doc.job_offer) {
            frappe.db.get_list('Job Offer', {
                filters: { 'job_applicant': frm.doc.job_applicant },
                fields: ['name'],
                limit: 1
            }).then(offers => {
                if (offers && offers.length > 0) {
                    frm.set_value('job_offer', offers[0].name);
                }
            });
        }

        // Step 2: Fetch blood group & emergency contact from Job Applicant
        frappe.db.get_value(
            'Job Applicant',
            frm.doc.job_applicant,
            ['custom_blood_group', 'custom_emergency_contact_number']
        ).then(r => {
            if (!r.message) return;
            let d = r.message;
            if (d.custom_blood_group)
                frm.set_value('custom_blood_group_', d.custom_blood_group);
            if (d.custom_emergency_contact_number)
                frm.set_value('custom_emergency_phone_number', d.custom_emergency_contact_number);
        });
    },

    // ── When Job Offer is set → fetch all key fields ──
    job_offer(frm) {
        if (!frm.doc.job_offer) return;

        frappe.db.get_value(
            'Job Offer',
            frm.doc.job_offer,
            ['job_applicant', 'company', 'applicant_name', 'designation',
             'custom_tentative_joining_date', 'custom_grade_']
        ).then(r => {
            if (!r.message) return;
            let d = r.message;

            if (d.job_applicant && !frm.doc.job_applicant)
                frm.set_value('job_applicant', d.job_applicant);
            if (d.company)
                frm.set_value('company', d.company);
            if (d.applicant_name)
                frm.set_value('employee_name', d.applicant_name);
            if (d.designation)
                frm.set_value('designation', d.designation);
            if (d.custom_tentative_joining_date)
                frm.set_value('date_of_joining', d.custom_tentative_joining_date);
            
            // Set Employee Grade here:
            if (d.custom_grade_)
                frm.set_value('employee_grade', d.custom_grade_);

            // Fetch department via Job Applicant → Job Opening
            let ja = d.job_applicant || frm.doc.job_applicant;
            if (ja) {
                frappe.db.get_value('Job Applicant', ja, 'job_title').then(r2 => {
                    if (!r2.message || !r2.message.job_title) return;
                    frappe.db.get_value('Job Opening', r2.message.job_title, 'department').then(r3 => {
                        if (r3.message && r3.message.department)
                            frm.set_value('department', r3.message.department);
                    });
                });
            }

            frappe.show_alert({
                message: __('Details auto-fetched from Job Offer ✅'),
                indicator: 'green'
            });
        });
    }
});

frappe.ui.form.on("Job Requisition", {
    custom_type_of_requirement: function(frm) {
        const is_replacement = frm.doc.custom_type_of_requirement === "Replacement";
        const replacement_fields = [
            "custom_name_of_employee_being_replaced",
            "custom_last_working_date",
            "custom_reason_for_replacement"
        ];

        replacement_fields.forEach(field => {
            frm.set_df_property(field, "reqd", is_replacement ? 1 : 0);
        });

        frm.refresh_fields();
    },

    refresh: function(frm) {
        // Hide the Status field via UI to bypass standard constraints
        frm.set_df_property('status', 'hidden', 1);

        // Trigger the replacement logic on load
        if (frm.doc.custom_type_of_requirement) {
            frm.trigger("custom_type_of_requirement");
        }

        // Rename 'Job Opening' in dashboard
        setTimeout(() => {
            if (frm.dashboard && frm.dashboard.wrapper) {
                // Find the badge link for Job Opening and change text
                frm.dashboard.wrapper.find('[data-doctype="Job Opening"] .badge-link').text("Create / View Job Opening");
            }
        }, 500);
    },

    // Auto-fetch employee details
    custom_name_of_employee_being_replaced: function(frm) {
        if (frm.doc.custom_name_of_employee_being_replaced) {
            frappe.db.get_value("Employee", frm.doc.custom_name_of_employee_being_replaced, 
                ["employee", "designation", "department"],
                function(r) {
                    if (r) {
                        frm.set_value("custom_employee_id", r.employee);
                        frm.set_value("custom_designation_of_employee", r.designation);
                        frm.set_value("custom_department_of_employee", r.department);
                    }
                }
            );
        }
    },

    // Intercept Workflow Reject Action to capture Reason
    before_workflow_action: function(frm) {
        if (frm.selected_workflow_action === "Reject") {
            return new Promise((resolve, reject) => {
                let d = new frappe.ui.Dialog({
                    title: 'Enter Rejection Reason',
                    fields: [
                        {
                            label: 'Reason',
                            fieldname: 'reason',
                            fieldtype: 'Small Text',
                            reqd: 1
                        }
                    ],
                    primary_action_label: 'Reject',
                    primary_action(values) {
                        frm.set_value('custom_rejection_reason', values.reason);
                        d.hide();
                        resolve(); // Proceed with rejection
                    }
                });
                d.custom_onhide = () => {
                    reject(); // Cancel rejection if dialog is closed
                };
                d.show();
            });
        }
    },

    after_workflow_action: function(frm) {
        // Automatically refresh to ensure background state changes (like auto-approvals) are immediately visible
        setTimeout(() => {
            frm.reload_doc();
        }, 800);
    },
});

frappe.ui.form.on('Interview', {
    refresh: function(frm) {
        // Hide the status field while creating or if it is still Pending (no feedback given)
        if (frm.doc.__islocal || frm.doc.status === 'Pending') {
            frm.set_df_property('status', 'hidden', 1);
        } else {
            frm.set_df_property('status', 'hidden', 0);
        }
    },
    show_feedback_dialog: async function (frm, data) {
        let fields = await frm.events.get_fields_for_feedback();

        let d = new frappe.ui.Dialog({
            title: __('Submit Feedback'),
            fields: [
                {
                    fieldname: 'skill_set',
                    fieldtype: 'Table',
                    label: __('Skill Assessment'),
                    cannot_add_rows: false,
                    in_editable_grid: true,
                    reqd: 1,
                    fields: fields,
                    data: data,
                },
                {
                    fieldname: 'result',
                    fieldtype: 'Select',
                    options: ['', 'Pending', 'Under Review', 'Cleared', 'Rejected', 'Cancelled'],
                    label: __('Result'),
                    reqd: 1,
                },
                {
                    fieldname: 'feedback',
                    fieldtype: 'Small Text',
                    label: __('Feedback'),
                },
            ],
            size: 'large',
            minimizable: true,
            static: true,
            primary_action: function (values) {
                frappe
                    .call({
                        method: 'hrms.hr.doctype.interview.interview.create_interview_feedback',
                        args: {
                            data: values,
                            interview_name: frm.doc.name,
                            interviewer: frappe.session.user,
                            job_applicant: frm.doc.job_applicant,
                        },
                    })
                    .then(() => {
                        // Force Frappe to pull the newly synced status from the backend database!
                        frm.reload_doc();
                    });
                d.hide();
            },
        });
        d.show();
